SELECT t.id,t.status,t.revision,r.actor_user_id,r.actor_team_id,c.project_id,r.canvas_id,t.run_id,t.permit_held,
t.cancel_requested cancelled,t.request_started_at IS NOT NULL started,t.received_at IS NOT NULL received
FROM afv_canvas_mcp_job t JOIN afv_canvas_run r ON r.id=t.run_id JOIN afv_canvas c ON c.id=r.canvas_id WHERE t.id = #{id}

SELECT t.id,t.status,t.revision,r.actor_user_id,r.actor_team_id,t.project_id,r.canvas_id,r.id run_id,t.permit_held,
t.cancel_requested cancelled,t.request_started_at IS NOT NULL started,t.received_at IS NOT NULL received
FROM afv_canvas_text_job t JOIN afv_canvas_run r ON r.id=t.run_id WHERE t.id = #{id}
